import './Item.css';
import { Link } from 'react-router-dom';
import { FaStar, FaStarHalfAlt, FaRegStar } from 'react-icons/fa'; // ⭐ star icons

const Item = (props) => {
  // Use first image if array, otherwise use the string
  const cardImage = Array.isArray(props.image) ? props.image[0] : props.image;

  // Sample rating and review (you can pass via props later)
  const rating = props.rating || 4.5;
  const reviews = props.reviews || 132;

  // Function to render stars
  const renderStars = (rating) => {
    const stars = [];
    for (let i = 1; i <= 5; i++) {
      if (rating >= i) stars.push(<FaStar key={i} className="star filled" />);
      else if (rating >= i - 0.5) stars.push(<FaStarHalfAlt key={i} className="star half" />);
      else stars.push(<FaRegStar key={i} className="star empty" />);
    }
    return stars;
  };

  return (
    <div className='item'>
      <Link to={`/product/${props.id}`}>
        <div className="item-image-wrapper">
          <img
            onClick={() => window.scrollTo(0, 0)}
            src={cardImage || '/placeholder.jpg'}
            alt={props.name}
          />
        </div>
      </Link>

      <p className="item-name">{props.name}</p>

      <div className="item-rating">
        <div className="stars">{renderStars(rating)}</div>
        <span className="reviews">({reviews} reviews)</span>
      </div>

      <div className="item-prices">
        <div className="item-price-new">Rs.{props.new_price}</div>
        <div className="item-price-old">Rs.{props.old_price}</div>
      </div>
    </div>
  );
};

export default Item;
